<?php $labels=['pending'=>'منتظر پرداخت','paid'=>'پرداخت‌شده','expired'=>'منقضی','canceled'=>'لغوشده','manual_review'=>'نیازمند بررسی','rejected'=>'ردشده'];?>
<section class="panel"><form class="filter-bar" method="get"><input name="q" value="<?= \CardPay\Core\View::e($filters['q']??'') ?>" placeholder="شناسه سفارش یا پرداخت"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach($labels as$key=>$label):?><option <?= ($filters['status']??'')===$key?'selected':'' ?> value="<?= $key ?>"><?= $label ?></option><?php endforeach;?></select><button class="btn secondary small">فیلتر</button></form><div class="table-wrap"><table><thead><tr><th>سفارش</th><th>مبلغ اصلی</th><th>مبلغ قابل پرداخت</th><th>وضعیت</th><th>تاریخ</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty">هنوز پرداختی ثبت نشده است.</div></td></tr><?php else:foreach($rows as$row):?><tr><td><strong><?= \CardPay\Core\View::e($row['external_order_id']?:'بدون شناسه سفارش') ?></strong><small><code><?= \CardPay\Core\View::e($row['public_id']) ?></code></small></td><td><?= number_format((int)$row['original_amount']) ?><small>ریال</small></td><td><strong><?= number_format((int)$row['payable_amount']) ?></strong><small>ریال — کد <?= (int)$row['token'] ?></small></td><td><span class="badge <?= $row['status']==='paid'?'success':($row['status']==='pending'?'warning':($row['status']==='manual_review'?'violet':'neutral')) ?>"><?= \CardPay\Core\View::e($labels[$row['status']]??$row['status']) ?></span></td><td><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row['created_at'],(string)($settings['timezone']??'Asia/Tehran'))) ?></td><td><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/payments/'.$row['public_id'])) ?>">جزئیات</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
